[{"order":1,"type":"heading","text":"PHP Operators: A Comprehensive Guide"},{"order":2,"type":"paragraph","text":"Operators are symbols that tell the PHP interpreter to perform specific mathematical, relational, or logical operations. This tutorial covers the fundamental operators in PHP: arithmetic, assignment, comparison, logical, and increment/decrement."},{"order":3,"type":"subheading","text":"Arithmetic Operators"},{"order":4,"type":"paragraph","text":"Arithmetic operators perform mathematical calculations."},{"order":5,"type":"bullet_point","text":"+ (Addition): Adds two operands. Example: '$x + $y'"},{"order":6,"type":"bullet_point","text":"- (Subtraction): Subtracts the second operand from the first. Example: '$x - $y'"},{"order":7,"type":"bullet_point","text":"* (Multiplication): Multiplies two operands. Example: '$x * $y'"},{"order":8,"type":"bullet_point","text":"/ (Division): Divides the first operand by the second. Example: '$x / $y'"},{"order":9,"type":"bullet_point","text":"% (Modulus): Returns the remainder of a division. Example: '$x % $y'"},{"order":10,"type":"bullet_point","text":"** (Exponentiation): Raises the first operand to the power of the second. Example: '$x ** $y'"},{"order":11,"type":"code","text":"&lt;?php
$x = 10;
$y = 5;

echo "Addition: " . ($x + $y) . "\n"; // Output: Addition: 15
echo "Subtraction: " . ($x - $y) . "\n"; // Output: Subtraction: 5
echo "Multiplication: " . ($x * $y) . "\n"; // Output: Multiplication: 50
echo "Division: " . ($x / $y) . "\n"; // Output: Division: 2
echo "Modulus: " . ($x % $y) . "\n"; // Output: Modulus: 0
echo "Exponentiation: " . ($x ** $y) . "\n"; // Output: Exponentiation: 100000
?&gt;"},{"order":12,"type":"subheading","text":"Assignment Operators"},{"order":13,"type":"paragraph","text":"Assignment operators are used to assign values to variables."},{"order":14,"type":"bullet_point","text":"= (Assignment): Assigns the value of the right operand to the left operand. Example: '$x = $y'"},{"order":15,"type":"bullet_point","text":"+= (Addition Assignment): Adds the right operand to the left operand and assigns the result to the left operand. Example: '$x += $y' (equivalent to '$x = $x + $y')"},{"order":16,"type":"bullet_point","text":"-= (Subtraction Assignment): Subtracts the right operand from the left operand and assigns the result to the left operand. Example: '$x -= $y' (equivalent to '$x = $x - $y')"},{"order":17,"type":"bullet_point","text":"*= (Multiplication Assignment): Multiplies the left operand by the right operand and assigns the result to the left operand. Example: '$x *= $y' (equivalent to '$x = $x * $y')"},{"order":18,"type":"bullet_point","text":"/= (Division Assignment): Divides the left operand by the right operand and assigns the result to the left operand. Example: '$x /= $y' (equivalent to '$x = $x / $y')"},{"order":19,"type":"bullet_point","text":"%= (Modulus Assignment): Calculates the modulus of the left operand by the right operand and assigns the result to the left operand. Example: '$x %= $y' (equivalent to '$x = $x % $y')"},{"order":20,"type":"bullet_point","text":"**= (Exponentiation Assignment): Raises the left operand to the power of the right operand and assigns the result to the left operand. Example: '$x **= $y' (equivalent to '$x = $x ** $y')"},{"order":21,"type":"code","text":"&lt;?php
$x = 10;
$y = 5;

$x += $y; // $x is now 15
echo "Addition Assignment: " . $x . "\n";

$x -= $y; // $x is now 10
echo "Subtraction Assignment: " . $x . "\n";

$x *= $y; // $x is now 50
echo "Multiplication Assignment: " . $x . "\n";

$x /= $y; // $x is now 10
echo "Division Assignment: " . $x . "\n";

$x %= $y; // $x is now 0
echo "Modulus Assignment: " . $x . "\n";

$x = 2;
$x **= $y; // $x is now 32
echo "Exponentiation Assignment: " . $x . "\n";
?&gt;"},{"order":22,"type":"subheading","text":"Comparison Operators"},{"order":23,"type":"paragraph","text":"Comparison operators compare two values and return a boolean result (true or false)."},{"order":24,"type":"bullet_point","text":"== (Equal): Returns true if the operands are equal. Example: '$x == $y'"},{"order":25,"type":"bullet_point","text":"=== (Identical): Returns true if the operands are equal and of the same type. Example: '$x === $y'"},{"order":26,"type":"bullet_point","text":"!= or &lt;&gt; (Not equal): Returns true if the operands are not equal. Example: '$x != $y' or '$x &lt;&gt; $y'"},{"order":27,"type":"bullet_point","text":"!== (Not identical): Returns true if the operands are not equal or not of the same type. Example: '$x !== $y'"},{"order":28,"type":"bullet_point","text":"> (Greater than): Returns true if the left operand is greater than the right operand. Example: '$x > $y'"},{"order":29,"type":"bullet_point","text":"< (Less than): Returns true if the left operand is less than the right operand. Example: '$x < $y'"},{"order":30,"type":"bullet_point","text":">= (Greater than or equal to): Returns true if the left operand is greater than or equal to the right operand. Example: '$x >= $y'"},{"order":31,"type":"bullet_point","text":"<= (Less than or equal to): Returns true if the left operand is less than or equal to the right operand. Example: '$x <= $y'"},{"order":32,"type":"code","text":"&lt;?php
$x = 10;
$y = "10";

var_dump($x == $y); // Output: bool(true)
var_dump($x === $y); // Output: bool(false)
var_dump($x != $y); // Output: bool(false)
var_dump($x !== $y); // Output: bool(true)

$a = 15;
$b = 5;

var_dump($a > $b);  // Output: bool(true)
var_dump($a < $b);  // Output: bool(false)
var_dump($a >= $b); // Output: bool(true)
var_dump($a <= $b); // Output: bool(false)
?&gt;"},{"order":33,"type":"subheading","text":"Logical Operators"},{"order":34,"type":"paragraph","text":"Logical operators combine two or more boolean expressions."},{"order":35,"type":"bullet_point","text":"and or && (And): Returns true if both operands are true. Example: '$x and $y' or '$x && $y'"},{"order":36,"type":"bullet_point","text":"or or || (Or): Returns true if either operand is true. Example: '$x or $y' or '$x || $y'"},{"order":37,"type":"bullet_point","text":"xor (Exclusive or): Returns true if one operand is true, but not both. Example: '$x xor $y'"},{"order":38,"type":"bullet_point","text":"! (Not): Returns true if the operand is false, and false if the operand is true. Example: '!$x'"},{"order":39,"type":"code","text":"&lt;?php
$x = true;
$y = false;

var_dump($x and $y);  // Output: bool(false)
var_dump($x && $y);   // Output: bool(false)
var_dump($x or $y);   // Output: bool(true)
var_dump($x || $y);   // Output: bool(true)
var_dump($x xor $y);  // Output: bool(true)
var_dump(!$x);     // Output: bool(false)
var_dump(!$y);     // Output: bool(true)
?&gt;"},{"order":40,"type":"subheading","text":"Increment/Decrement Operators"},{"order":41,"type":"paragraph","text":"Increment and decrement operators increase or decrease the value of a variable by one."},{"order":42,"type":"bullet_point","text":"++$x (Pre-increment): Increments '$x' by one, then returns '$x'."},{"order":43,"type":"bullet_point","text":"$x++ (Post-increment): Returns '$x', then increments '$x' by one."},{"order":44,"type":"bullet_point","text":"--$x (Pre-decrement): Decrements '$x' by one, then returns '$x'."},{"order":45,"type":"bullet_point","text":"$x-- (Post-decrement): Returns '$x', then decrements '$x' by one."},{"order":46,"type":"code","text":"&lt;?php
$x = 5;

echo "Pre-increment: " . ++$x . "\n"; // Output: Pre-increment: 6

$y = 5;
echo "Post-increment: " . $y++ . "\n"; // Output: Post-increment: 5
echo "Value of y after post-increment: " . $y . "\n"; // Output: Value of y after post-increment: 6

$z = 5;
echo "Pre-decrement: " . --$z . "\n"; // Output: Pre-decrement: 4

$w = 5;
echo "Post-decrement: " . $w-- . "\n"; // Output: Post-decrement: 5
echo "Value of w after post-decrement: " . $w . "\n"; // Output: Value of w after post-decrement: 4
?&gt;"}]
